  function applyPrefs(){ document.documentElement.classList.toggle('reduced-motion', !!state.prefs.reducedMotion); document.documentElement.classList.toggle('high-contrast', !!state.prefs.highContrast); const scale=Math.max(.9,Math.min(1.25,Number(state.prefs.textScale)||1)); document.documentElement.style.setProperty('--wwg-text-scale',scale); document.documentElement.classList.toggle('text-scaled',Math.abs(scale-1)>.001); }
  applyPrefs();
  function isNew(g){ const age=(Date.now()-new Date(g.added+'T12:00:00').getTime())/86400000; return age>=0&&age<=7; }
  function isUpdated(g){return !!g.version&&g.version!=='1.0'}
  function ratingText(g){ const r=Number(state.ratings[g.id]||0); return r?`★ ${r}/5`:'Unrated'; }
  function gameCard(g, mini=false) {
    const plays=state.plays[g.id]||0, mins=playMinutes(g.id), fav=state.favorites.includes(g.id), score=state.scores[g.id], cleared=gameCleared(g);
    return `<article class="game-card ${mini?'mini':''}" data-id="${g.id}"><a class="cover-link" href="game.html?id=${encodeURIComponent(g.id)}" aria-label="Play ${esc(g.title)}"><img src="${g.cover}" alt="${esc(g.title)} cover art" /></a><div class="card-body"><div class="card-topline"><span>${isNew(g)?'<b class="new-badge">NEW</b> ':''}${isUpdated(g)?`<b class="update-badge">v${esc(g.version)}</b> `:''}${cleared?'<b class="clear-badge">CLEARED</b> ':''}${esc(g.genres[0])}</span><span class="card-actions"><button class="favorite ${fav?'active':''}" data-favorite="${g.id}" aria-label="${fav?'Remove from':'Add to'} favorites">${fav?'♥':'♡'}</button><button class="later ${state.playLater.includes(g.id)?'active':''}" data-later="${g.id}" aria-label="${state.playLater.includes(g.id)?'Remove from':'Add to'} Play Later">${state.playLater.includes(g.id)?'✓':'＋'}</button></span></div><h3><a href="game.html?id=${encodeURIComponent(g.id)}">${esc(g.title)}</a></h3>${mini?'':`<p>${esc(g.tagline)}</p>`}<div class="card-meta"><span>${plays?plays+' local play'+(plays===1?'':'s'):'Ready to play'}${mins?' / '+mins+' min':''}</span><span>${score!=null?'Best '+Number(score).toLocaleString()+' '+esc(g.scoreMeta?.unit||'pts')+(g.scoreMeta?.direction==='low'?' ↓':''):ratingText(g)}</span>${mini?'':`<span>${isUpdated(g)?'Updated '+fmt(g.updated||g.added):fmt(g.added)}</span>`}</div>${mini?'':`<div class="cap-row">${[...capabilities(g),...playModes(g)].map(x=>`<span>${x}</span>`).join('')}</div>`}</div></article>`;
  }
  function restoreDiscoveryUrl(){if(!location.protocol.startsWith('http'))return;const p=new URLSearchParams(location.search),v=(k,allowed,fallback)=>allowed.includes(p.get(k))?p.get(k):fallback;state.query=(p.get('q')||'').slice(0,120);state.category=v('genre',categories,'All');state.input=v('input',['All','Keyboard','Touch','Gamepad','Remappable'],'All');state.mode=v('mode',['All','Solo','Local Multiplayer'],'All');state.status=v('status',['All','Unplayed','In Progress','Uncleared','Fresh Genre','Favorites','Cleared','Play Later'],'All');state.collection=v('collection',Object.keys(collections),'All');state.sort=v('sort',['featured','new','popular','rated','time','updated','az'],'featured');}
  function syncDiscoveryUrl(){if(!location.protocol.startsWith('http'))return;const p=new URLSearchParams();if(state.query)p.set('q',state.query);if(state.category!=='All')p.set('genre',state.category);if(state.input!=='All')p.set('input',state.input);if(state.mode!=='All')p.set('mode',state.mode);if(state.status!=='All')p.set('status',state.status);if(state.collection!=='All')p.set('collection',state.collection);if(state.sort!=='featured')p.set('sort',state.sort);const qs=p.toString();history.replaceState(null,'',location.pathname+(qs?'?'+qs:'')+location.hash);}
  function syncDiscoveryControls(){if($('#searchInput'))$('#searchInput').value=state.query;if($('#inputFilter'))$('#inputFilter').value=state.input;if($('#modeFilter'))$('#modeFilter').value=state.mode;if($('#statusFilter'))$('#statusFilter').value=state.status;if($('#collectionFilter'))$('#collectionFilter').value=state.collection;if($('#sortSelect'))$('#sortSelect').value=state.sort;}
  function renderLibrary(){ let list=games.filter(g=>(state.category==='All'||g.genres.includes(state.category))&&(state.input==='All'||capabilities(g).includes(state.input))&&(state.mode==='All'||playModes(g).includes(state.mode))&&(state.collection==='All'||(collections[state.collection]||collections.All)(g))&&(state.status==='All'||(state.status==='Unplayed'&&!state.plays[g.id])||(state.status==='In Progress'&&Number(state.plays[g.id]||0)>0&&!gameCleared(g))||(state.status==='Uncleared'&&!gameCleared(g))||(state.status==='Fresh Genre'&&freshPrimaryGenre(g))||(state.status==='Favorites'&&state.favorites.includes(g.id))||(state.status==='Cleared'&&gameCleared(g))||(state.status==='Play Later'&&state.playLater.includes(g.id)))&&(`${g.title} ${g.tagline} ${g.description} ${g.genres.join(' ')}`).toLowerCase().includes(state.query.toLowerCase())); list.sort((a,b)=>state.sort==='new'?b.added.localeCompare(a.added)||b.basePopularity-a.basePopularity:state.sort==='popular'?(b.basePopularity+(state.plays[b.id]||0)*3)-(a.basePopularity+(state.plays[a.id]||0)*3):state.sort==='rated'?(state.ratings[b.id]||0)-(state.ratings[a.id]||0)||b.basePopularity-a.basePopularity:state.sort==='time'?(Number(state.playtime[b.id]||0)-Number(state.playtime[a.id]||0)||b.basePopularity-a.basePopularity):state.sort==='updated'?(String(b.updated||b.added).localeCompare(String(a.updated||a.added))||Number(!!b.version)-Number(!!a.version)||b.basePopularity-a.basePopularity):state.sort==='az'?a.title.localeCompare(b.title):Number(b.featured)-Number(a.featured)||b.basePopularity-a.basePopularity); $('#gameGrid').innerHTML=list.map(g=>gameCard(g)).join(''); $('#emptyState').hidden=!!list.length; wireFavorites(); wireLater(); }
  function renderChips(){ $('#categoryChips').innerHTML=categories.map(c=>`<button class="chip ${c===state.category?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join(''); document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;syncDiscoveryUrl();renderChips();renderLibrary();})); }
  function wireFavorites(){ document.querySelectorAll('[data-favorite]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();const id=b.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];localStorage.setItem('wwg:favorites',JSON.stringify(state.favorites));renderLibrary();renderPersonal();renderRecommendations();})); }
  function wireLater(){ document.querySelectorAll('[data-later]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();const id=b.dataset.later;state.playLater=state.playLater.includes(id)?state.playLater.filter(x=>x!==id):[...state.playLater,id];localStorage.setItem('wwg:play-later',JSON.stringify(state.playLater));renderLibrary();renderPersonal();renderRecommendations();})); }
  function renderAchievements(){ const unlocked=achievements.filter(a=>a.test()).length; $('#achievementGrid').innerHTML=achievements.map(a=>`<div class="achievement ${a.test()?'unlocked':''}"><span class="achievement-icon">${a.test()?'◆':'◇'}</span><div><strong>${esc(a.name)}</strong><small>${esc(a.desc)}</small><em>${a.progress()}</em></div></div>`).join(''); return unlocked; }
  function renderScores(){ const list=Object.entries(state.scores).map(([id,v])=>({game:games.find(g=>g.id===id),score:Number(v),at:String(state.runs[id]?.at||'')})).filter(x=>x.game&&Number.isFinite(x.score)).sort((a,b)=>b.at.localeCompare(a.at)||a.game.title.localeCompare(b.game.title)).slice(0,8); $('#scoreBoard').innerHTML=list.length?list.map((x,i)=>`<a class="score-row" href="game.html?id=${encodeURIComponent(x.game.id)}"><span><b>${i+1}</b>${esc(x.game.title)}<small>${x.game.scoreMeta?.direction==='low'?'lower is better':'higher is better'}</small></span><strong>${x.score.toLocaleString()} ${esc(x.game.scoreMeta?.unit||'pts')} ${x.game.scoreMeta?.direction==='low'?'↓':'↑'}</strong></a>`).join(''):'<p class="muted">Supported games will post local best scores here.</p>'; const rawRuns=Array.isArray(state.runHistory)&&state.runHistory.length?state.runHistory:Object.entries(state.runs).map(([id,r])=>({id,...r}));const runs=rawRuns.map(r=>({game:games.find(g=>g.id===r.id),r})).filter(x=>x.game&&x.r&&Number.isFinite(Number(x.r.score))).sort((a,b)=>String(b.r.at||'').localeCompare(String(a.r.at||''))).slice(0,8);if($('#runHistory'))$('#runHistory').innerHTML=runs.length?runs.map(x=>`<a class="score-row run-row" href="game.html?id=${encodeURIComponent(x.game.id)}"><span>${esc(x.game.title)}<small>${esc(String(x.r.event||'run').replaceAll('-', ' '))}${Number.isFinite(Number(x.r.duration))?` • ${Number(x.r.duration).toLocaleString()}s`:''}</small></span><strong>${Number(x.r.score).toLocaleString()} ${esc(x.game.scoreMeta?.unit||'pts')}</strong></a>`).join(''):'<p class="muted">Your latest scored runs will appear here with event and duration metadata when available.</p>'; }

  function renderActivity(){const el=$('#activityChart');if(!el)return;const days=[];for(let i=6;i>=0;i--){const d=new Date(today+'T12:00:00');d.setDate(d.getDate()-i);const key=d.toLocaleDateString('en-CA'),sec=Number(state.dailyPlaytime[key]||0);days.push({key,label:d.toLocaleDateString(undefined,{weekday:'short'}),min:Math.floor(sec/60)})}const max=Math.max(1,...days.map(d=>d.min));el.innerHTML=days.map(d=>`<div class="activity-day" title="${esc(d.key)} · ${d.min} min"><span>${d.min?d.min+'m':'—'}</span><i style="height:${Math.max(4,Math.round(d.min/max*64))}px"></i><b>${esc(d.label)}</b></div>`).join('')}
  function renderGenreTrends(){const el=$('#genreTrends');if(!el)return;const list=Object.entries(recentGenreTotals()).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,5),max=Math.max(1,...list.map(x=>x[1]));el.innerHTML=list.length?list.map(([genre,sec])=>`<div class="genre-trend"><span>${esc(genre)}</span><i style="width:${Math.max(6,Math.round(sec/max*100))}%"></i><b>${Math.max(1,Math.floor(sec/60))}m</b></div>`).join(''):'<p class="muted">Play games this week to build a private genre activity map.</p>';}
